def solve(g):
    H=len(g);W=len(g[0])
    sepR={r for r in range(H) if all(x==8 for x in g[r])}
    sepC={c for c in range(W) if all(g[r][c]==8 for r in range(H))}
    # rowbands
    rb=[];s0=0
    for r in sorted(sepR|{H}):
        if s0<r: rb.append((s0,r-1)); s0=r+1
    cb=[];s0=0
    for c in sorted(sepC|{W}):
        if s0<c: cb.append((s0,c-1)); s0=c+1
    out=[[None]*W for _ in range(H)]
    for (a,b) in rb:
        mcols=sorted({g[r][c] for r in range(a,b+1) for c in range(W) if c not in sepC and g[r][c] not in (0,8)})
        if not mcols: continue
        v=mcols[0]
        # find marker col in this band (first non-zero non-8)
        cols=sorted({c for r in range(a,b+1) for c in range(W) if c not in sepC and g[r][c]!=0 and g[r][c]!=8})
        for (c0,c1) in cb:
            if any(c0<=c<=c1 for c in cols):
                for cc in range(c0,c1+1): out[cc]=(a,b,v)
    return out
